const dayDate=k=>{const [y,m,d]=k.split('-').map(Number);return new Date(y,m-1,d,12)};
const addDays=(d,n)=>{const x=new Date(d);x.setDate(x.getDate()+n);return x};
const today=()=>{const d=new Date();d.setHours(0,0,0,0);return d};
const weekLogs=()=>{const start=today();start.setDate(start.getDate()-6);return data.logs.filter(l=>new Date(l.date)>=start)};
const volume=l=>(l.exercises||[]).reduce((a,e)=>a+(e.sets||[]).reduce((b,s)=>b+(s.done&&!s.warmup?(+s.weight||0)*(+s.reps||0):0),0),0);
const doneSets=l=>(l.exercises||[]).reduce((a,e)=>a+(e.sets||[]).filter(s=>s.done).length,0);
