function toast(t){const el=$('#toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2400)}
function syncState(mode,label){const p=$('#syncPill');p.classList.remove('syncing','error');if(['syncing','pending'].includes(mode))p.classList.add('syncing');if(mode==='error')p.classList.add('error');$('#syncText').textContent=label}
function normalizeData(x){const b=fresh();return {...b,...(x||{}),profile:{...b.profile,...((x||{}).profile||{})},customExercises:Array.isArray(x?.customExercises)?x.customExercises:[],bodyLogs:Array.isArray(x?.bodyLogs)?x.bodyLogs:[],challenge:{done:{},...(x?.challenge||{})},meta:{...b.meta,...(x?.meta||{})}}}
function switchCloudUser(uid){if(!uid)return;const previous=localStorage.getItem(ACTIVE_UID);if(previous===uid)return;if(previous)localStorage.setItem(USER_STORE+previous,JSON.stringify(data));const stored=json(localStorage.getItem(USER_STORE+uid),null);if(stored)data=normalizeData(stored);else if(previous)data=fresh();localStorage.setItem(ACTIVE_UID,uid);localStorage.setItem(STORE,JSON.stringify(data));localStorage.setItem(USER_STORE+uid,JSON.stringify(data))}
