function nav(target){if(target==='session'&&!data.activeSession)target='train';screen=target;$$('.screen').forEach(x=>x.classList.toggle('active',x.id===target));$$('.tab[data-go]').forEach(x=>x.classList.toggle('active',x.dataset.go===target||(target==='session'&&x.dataset.go==='train')));const renderers={home:renderHome,train:renderRoutines,progress:renderProgress,body:renderBody,profile:renderProfile};if(target!=='session')renderers[target]?.();window.scrollTo({top:0,behavior:'smooth'})}
