function todaysRoutine(){const d=DAYS[new Date().getDay()];return data.routines.find(r=>r.day===d)||data.routines.find(r=>r.day==='Flexível')||null}
function lastLoad(name){for(const log of [...data.logs].sort((a,b)=>new Date(b.date)-new Date(a.date))){const ex=(log.exercises||[]).find(x=>x.name.toLowerCase()===name.toLowerCase());const sets=(ex?.sets||[]).filter(s=>s.done&&!s.warmup&&Number(s.weight)>0);if(sets.length)return String(sets.at(-1).weight)}return ''}
function streak(){const days=new Set(completedLogs().map(l=>key(l.date)));let d=today(),n=0;if(!days.has(key(d)))d=addDays(d,-1);while(days.has(key(d))&&n<400){n++;d=addDays(d,-1)}return n}
function renderAll(){renderHome();renderRoutines();renderProgress();renderBody();renderProfile()}
function dailyVolumes(count=7){const t=today();return Array.from({length:count},(_,i)=>{const d=addDays(t,i-count+1),k=key(d);return{label:SHORT[d.getDay()],value:data.logs.filter(l=>key(l.date)===k).reduce((s,l)=>s+volume(l),0),date:k}})}
function bars(points,h=145){const max=Math.max(1,...points.map(x=>x.value)),base=h-28,bh=h-70,step=320/points.length;const grid=[.25,.5,.75,1].map(v=>`<line x1="8" y1="${base-bh*v}" x2="332" y2="${base-bh*v}" stroke="#a7c4e0" stroke-opacity=".09"/>`).join('');const content=points.map((p,i)=>{const height=p.value?Math.max(4,p.value/max*bh):3,x=10+i*step+step*.25,w=step*.48;return `<rect x="${x}" y="${base-height}" width="${w}" height="${height}" rx="5" fill="${p.value?'url(#barGrad)':'#8fa6c0'}" opacity="${p.value?1:.22}"/><text x="${x+w/2}" y="${h-7}" fill="#8fa6c0" font-size="9" text-anchor="middle">${p.label}</text>`}).join('');return `<defs><linearGradient id="barGrad" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#81c0ff"/><stop offset="1" stop-color="#c9f36a"/></linearGradient></defs>${grid}${content}`}

function renderHome(){const now=new Date();$('#todayLabel').textContent=now.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'}).toUpperCase();$('#streakNum').textContent=streak();const monday=addDays(today(),-((now.getDay()+6)%7));$('#weekStrip').innerHTML=Array.from({length:7},(_,i)=>{const d=addDays(monday,i),k=key(d),done=completedLogs().some(l=>key(l.date)===k),isToday=k===key(new Date());return `<div class="day-pill ${done?'done':''} ${isToday?'today':''}">${SHORT[(i+1)%7]}<b>${d.getDate()}</b><span class="day-mark">${done?'✓':isToday?'HOJE':'·'}</span></div>`}).join('');const r=todaysRoutine();$('#todayWorkoutTitle').textContent=r?.name||'Dia de recuperação';$('#todayWorkoutTag').textContent=r?.day?.toUpperCase()||'PAUSA';$('#todayCard').innerHTML=r?`<span class="eyebrow">${r.items.length} EXERCÍCIOS · ${r.items.reduce((a,x)=>a+(+x[1]||0),0)} SÉRIES PLANEJADAS</span><h3>${esc(r.name)}</h3><p>Entre com calma, execute bem e registre o que realmente fez.</p><div class="card-meta"><span>◷ ${Math.max(25,r.items.length*8)}–${Math.max(35,r.items.length*12)} min estimados</span><span>◉ ${esc(data.profile.goal)}</span></div><button class="primary full" id="startToday">Começar treino ↗</button>`:`<span class="eyebrow">RECUPERAÇÃO TAMBÉM É TREINO</span><h3>Hoje não há divisão marcada.</h3><p>Use o dia para descansar, fazer mobilidade leve ou organizar sua próxima sessão.</p><div class="card-meta">Seu próximo treino aparece aqui automaticamente.</div><button class="secondary full" id="viewRoutines">Ver minha semana</button>`;$('#startToday')?.addEventListener('click',()=>startWorkout(r.id));$('#viewRoutines')?.addEventListener('click',()=>nav('train'));const logs=weekLogs(),v=logs.reduce((a,l)=>a+volume(l),0);$('#weekCount').textContent=logs.filter(l=>doneSets(l)>0).length;$('#weekVolume').innerHTML=`${fmt(v)} <small>${esc(data.profile.unit)}</small>`;$('#chartTotal').textContent=`${fmt(v)} ${data.profile.unit}`;$('#homeChart').innerHTML=bars(dailyVolumes());renderChallenge()}
function renderChallenge(){const start=data.profile.challengeStart?dayDate(data.profile.challengeStart):null,card=$('#challengeCard');if(!start){card.innerHTML=`<div class="challenge-intro"><div><b>Uma semana para criar consistência.</b><p>Pequenas ações, registradas dia após dia.</p></div><button class="primary small" id="startChallenge">Começar</button></div><p class="challenge-note">O objetivo é organizar hábitos, não prometer transformação física rápida.</p>`;$('#startChallenge').onclick=()=>{data.profile.challengeStart=key(new Date());data.challenge.done={};save();renderChallenge();toast('Seu ciclo de 7 dias começou!')};$('#challengeProgress').textContent='Não iniciado';return}const task=[['Organize seu ponto de partida','Defina seus dias de treino e confira suas divisões.'],['Registre uma sessão','Anote cargas, repetições e como foi a execução.'],['Revise a técnica','Priorize movimento controlado e sem dor.'],['Respeite a recuperação','Sono e pausa fazem parte da rotina.'],['Repita o que funciona','Conclua a sessão prevista ou ajuste o plano.'],['Observe os dados','Compare com a sessão anterior sem forçar recordes.'],['Feche a semana','Revise frequência, cargas e próximos ajustes.']];const delta=Math.floor((today()-start)/86400000),selected=Math.max(0,Math.min(6,delta)),selectedKey=key(addDays(start,selected)),doneCount=Object.values(data.challenge.done||{}).filter(Boolean).length;card.innerHTML=`<div class="challenge-intro"><div><b>Seu ciclo de 7 dias</b><p>${delta<0?'Começa em breve':delta>6?'Ciclo concluído — reveja seus registros':`Dia ${selected+1} de 7 · ${doneCount} ações marcadas`}</p></div><button class="text-btn" id="restartChallenge">Recomeçar</button></div><div class="challenge-days">${Array.from({length:7},(_,i)=>{const k=key(addDays(start,i)),done=!!data.challenge.done[k];return `<button class="challenge-day ${done?'done':''} ${i===selected?'today':''}" data-challenge-day="${k}"><b>${i+1}</b>${done?'✓':addDays(start,i).getDate()}</button>`}).join('')}</div><div class="challenge-task"><div><b>${task[selected][0]}</b><p>${task[selected][1]}</p></div><button class="primary small" id="toggleChallenge">${data.challenge.done[selectedKey]?'Desmarcar':'Concluir'}</button></div>`;$('#challengeProgress').textContent=`${doneCount}/7 concluídos`;$$('[data-challenge-day]',card).forEach(btn=>btn.onclick=()=>{const index=Math.max(0,Math.min(6,Math.round((dayDate(btn.dataset.challengeDay)-start)/86400000)));$$('.challenge-day',card).forEach((x,i)=>x.classList.toggle('today',i===index));$('.challenge-task',card).innerHTML=`<div><b>${task[index][0]}</b><p>${task[index][1]}</p></div><button class="primary small" id="toggleChallenge">${data.challenge.done[btn.dataset.challengeDay]?'Desmarcar':'Concluir'}</button>`;$('#toggleChallenge').onclick=()=>{data.challenge.done[btn.dataset.challengeDay]=!data.challenge.done[btn.dataset.challengeDay];save();renderChallenge()}});$('#toggleChallenge').onclick=()=>{data.challenge.done[selectedKey]=!data.challenge.done[selectedKey];save();renderChallenge()};$('#restartChallenge').onclick=()=>{if(confirm('Recomeçar os sete dias? O histórico de treinos será mantido.')){data.profile.challengeStart=key(new Date());data.challenge.done={};save();renderChallenge()}}}

function renderRoutines(){const order=DAYS.slice(1).concat(DAYS[0]);$('#weekPlan').innerHTML=order.map(d=>{const r=data.routines.find(x=>x.day===d);return `<div class="week-plan-item ${r?'has-workout':''}"><b>${SHORT[DAYS.indexOf(d)]}</b><span>${r?esc(r.name.split('—').at(-1).trim().split(' ')[0]):'—'}</span></div>`}).join('');$('#routineList').innerHTML=data.routines.length?data.routines.map(r=>`<article class="routine-item"><div class="routine-top"><div><h3>${esc(r.name)}</h3><div class="routine-meta">${r.items.length} exercícios · ${r.items.reduce((a,x)=>a+(+x[1]||0),0)} séries planejadas</div></div><span class="routine-day">${esc(r.day.toUpperCase())}</span></div><div class="routine-exercises">${r.items.slice(0,5).map((x,i)=>`${i+1}. ${esc(x[0])} · ${x[1]} × ${x[2]}`).join('<br>')}${r.items.length>5?`<br>+ ${r.items.length-5} exercícios`:''}</div><div class="routine-actions"><button class="primary" data-start-routine="${r.id}">Iniciar</button><button class="secondary" data-edit-routine="${r.id}">Editar</button><button class="secondary" data-delete-routine="${r.id}">×</button></div></article>`).join(''):`<div class="glass-card empty">Você ainda não criou uma divisão.</div>`;$$('[data-start-routine]').forEach(b=>b.onclick=()=>startWorkout(b.dataset.startRoutine));$$('[data-edit-routine]').forEach(b=>b.onclick=()=>openRoutine(data.routines.find(r=>r.id===b.dataset.editRoutine)));$$('[data-delete-routine]').forEach(b=>b.onclick=()=>{if(confirm('Excluir esta divisão? Os treinos concluídos não serão apagados.')){data.routines=data.routines.filter(r=>r.id!==b.dataset.deleteRoutine);save();renderAll()}});renderLibrary()}
function openRoutine(r=null){editingId=r?.id||null;$('#routineDialogTitle').textContent=r?'Editar divisão':'Nova divisão';$('#routineName').value=r?.name||'';$('#routineDay').value=r?.day||'Segunda';$('#routineItems').value=(r?.items||[['Supino reto com barra',3,10],['Remada baixa',3,12]]).map(x=>x.join(' | ')).join('\n');$('#routineDialog').showModal()}
$('#addWorkoutBtn').onclick=()=>openRoutine();$('#routineForm').onsubmit=e=>{e.preventDefault();const items=$('#routineItems').value.split('\n').map(s=>s.split('|').map(x=>x.trim())).filter(x=>x[0]).map(x=>[x[0],Math.max(1,Math.min(20,+x[1]||3)),Math.max(1,Math.min(100,+x[2]||10))]);if(!items.length){toast('Inclua ao menos um exercício.');return}const r={id:editingId||id(),name:$('#routineName').value.trim(),day:$('#routineDay').value,items};if(editingId)data.routines=data.routines.map(x=>x.id===editingId?r:x);else data.routines.push(r);save();$('#routineDialog').close();renderAll();toast('Divisão salva.')};
