function renderLibrary(){const all=[...EXERCISES,...data.customExercises],query=($('#exerciseSearch')?.value||'').trim().toLowerCase(),muscles=['Todos',...new Set(all.map(x=>x.muscle))];$('#muscleFilters').innerHTML=muscles.map(m=>`<button class="filter-chip ${libraryMuscle===m?'active':''}" data-muscle="${esc(m)}">${esc(m)}</button>`).join('');$$('[data-muscle]').forEach(b=>b.onclick=()=>{libraryMuscle=b.dataset.muscle;renderLibrary()});const rows=all.filter(x=>(libraryMuscle==='Todos'||x.muscle===libraryMuscle)&&(!query||`${x.name} ${x.muscle} ${x.equipment}`.toLowerCase().includes(query)));$('#libraryList').innerHTML=rows.length?rows.map(x=>`<article class="library-item"><div><h4>${esc(x.name)}</h4><p>${esc(x.muscle)} · ${esc(x.equipment)}${x.custom?' · personalizado':''}</p></div><button data-add-exercise="${esc(x.name)}">+ Rotina</button></article>`).join(''):`<div class="glass-card empty">Nenhum exercício encontrado.</div>`;$$('[data-add-exercise]').forEach(b=>b.onclick=()=>{if(!data.routines.length){toast('Crie uma divisão primeiro.');openRoutine();return}const choices=data.routines.map((r,i)=>`${i+1}. ${r.name}`).join('\n'),answer=prompt(`Adicionar ${b.dataset.addExercise} a qual divisão?\n${choices}\nDigite o número:`);if(answer===null)return;const r=data.routines[Number(answer)-1];if(!r){toast('Número inválido.');return}r.items.push([b.dataset.addExercise,3,10]);save();renderRoutines();toast('Exercício adicionado.')})}
